export default function CropRecommender() {
  const { currentLang, t } = useLanguage();

  // Form input state
  const [climateZone, setClimateZone] = useState('subtropical');
  const [soilType, setSoilType] = useState('alluvial');
  const [nitrogen, setNitrogen] = useState(100);
  const [phosphorus, setPhosphorus] = useState(55);
  const [potassium, setPotassium] = useState(50);
  const [phLevel, setPhLevel] = useState(6.8);
  const [waterAvailability, setWaterAvailability] = useState('canal');
  const [season, setSeason] = useState('rabi');

  // Active modal crop
  const [selectedCropForPlan, setSelectedCropForPlan] = useState(null);

  // Reset to balanced defaults
  const handleReset = () => {
    setClimateZone('subtropical');
    setSoilType('alluvial');
    setNitrogen(90);
    setPhosphorus(50);
    setPotassium(45);
    setPhLevel(6.8);
    setWaterAvailability('canal');
    setSeason('rabi');
  };

  // Agronomic Suitability Engine
  const rankedCrops = useMemo(() => {
    const scored = cropsDatabase.map(crop => {
      let score = 0;

      // 1. Season Alignment (Max 30 pts)
      if (crop.seasons.includes(season)) {
        score += 30;
      } else {
        score += 8;
      }

      // 2. Soil Type Compatibility (Max 20 pts)
      if (crop.soilTypes.includes(soilType)) {
        score += 20;
      } else {
        score += 7;
      }

      // 3. Climate Zone Fit (Max 15 pts)
      if (crop.climateZones.includes(climateZone)) {
        score += 15;
      } else {
        score += 6;
      }

      // 4. Soil Nutrients N-P-K match (Max 20 pts)
      const midN = (crop.nRange[0] + crop.nRange[1]) / 2;
      const midP = (crop.pRange[0] + crop.pRange[1]) / 2;
      const midK = (crop.kRange[0] + crop.kRange[1]) / 2;

      const nDiff = Math.abs(nitrogen - midN) / 100;
      const pDiff = Math.abs(phosphorus - midP) / 70;
      const kDiff = Math.abs(potassium - midK) / 80;

      const nScore = Math.max(0, 7 * (1 - nDiff));
      const pScore = Math.max(0, 7 * (1 - pDiff));
      const kScore = Math.max(0, 6 * (1 - kDiff));
      score += (nScore + pScore + kScore);

      // 5. pH Tolerance (Max 10 pts)
      if (phLevel >= crop.phRange[0] && phLevel <= crop.phRange[1]) {
        score += 10;
      } else {
        const phDist = Math.min(
          Math.abs(phLevel - crop.phRange[0]), 
          Math.abs(phLevel - crop.phRange[1])
        );
        score += Math.max(0, 10 - phDist * 6);
      }

      // 6. Water feasibility (Max 5 pts)
      if (waterAvailability === 'drip' || crop.waterTypes.includes(waterAvailability)) {
        score += 5;
      } else {
        score += 2;
      }

      // Final percentage normalized to 65% - 98%
      const matchPercentage = Math.min(98, Math.max(62, Math.round(score)));

      return {
        ...crop,
        matchPercentage
      };
    });

    return scored.sort((a, b) => b.matchPercentage - a.matchPercentage);
  }, [season, soilType, climateZone, nitrogen, phosphorus, potassium, phLevel, waterAvailability]);

  // Top recommended crop for radar comparison
  const topCrop = rankedCrops[0];

  // Radar chart data: User's NPK vs Ideal crop NPK
  const radarData = useMemo(() => {
    if (!topCrop) return [];
    const idealN = (topCrop.nRange[0] + topCrop.nRange[1]) / 2;
    const idealP = (topCrop.pRange[0] + topCrop.pRange[1]) / 2;
    const idealK = (topCrop.kRange[0] + topCrop.kRange[1]) / 2;
    const idealPH = ((topCrop.phRange[0] + topCrop.phRange[1]) / 2) * 15; // Scaled for radar
    const userPHScaled = phLevel * 15;

    return [
      { parameter: 'Nitrogen (N)', current: nitrogen, optimal: Math.round(idealN) },
      { parameter: 'Phosphorus (P)', current: phosphorus, optimal: Math.round(idealP) },
      { parameter: 'Potassium (K)', current: potassium, optimal: Math.round(idealK) },
