import React, { useState } from 'react';
import { useLanguage } from '../context/LanguageContext';
import { diseasesDatabase } from '../data/diseasesData';
import { 
  Stethoscope, 
  AlertTriangle, 
  CheckCircle2, 
  RotateCcw, 
  Leaf, 
  ShieldCheck, 
  FlaskConical, 
  Upload, 
  Sparkles,
  Camera,
  Info
} from 'lucide-react';

export default function CropDoctor() {
  const { currentLang, t } = useLanguage();

  const [selectedCrop, setSelectedCrop] = useState('tomato');
  const [selectedPart, setSelectedPart] = useState('leaf');
  const [selectedSymptoms, setSelectedSymptoms] = useState(['brown-spots', 'yellowing']);
  const [activeDiagnosis, setActiveDiagnosis] = useState(diseasesDatabase[0]);
  const [uploadedPreview, setUploadedPreview] = useState(null);

  const symptomList = [
    { id: 'yellowing', label: 'Yellowing / Chlorosis' },
    { id: 'brown-spots', label: 'Brown / Black Spots' },
    { id: 'wilting', label: 'Wilting / Drooping' },
    { id: 'leaf-curl', label: 'Leaf Curling / Cupping' },
    { id: 'stunted', label: 'Stunted Bushy Growth' },
  ];

  const handleToggleSymptom = (symptomId) => {
    setSelectedSymptoms(prev => 
      prev.includes(symptomId)
        ? prev.filter(s => s !== symptomId)
        : [...prev, symptomId]
    );
  };

  const handleDiagnose = () => {
    // Find closest match in diseasesDatabase
    const matched = diseasesDatabase.find(d => 
      d.cropId === selectedCrop && 
      (d.part === selectedPart || d.symptoms.some(s => selectedSymptoms.includes(s)))
    ) || diseasesDatabase.find(d => d.cropId === selectedCrop) || diseasesDatabase[0];

    setActiveDiagnosis(matched);
  };

  const handleSelectSample = (disease) => {
    setSelectedCrop(disease.cropId);
    setSelectedPart(disease.part);
    setSelectedSymptoms(disease.symptoms);
    setActiveDiagnosis(disease);
    setUploadedPreview(disease.sampleImage);
  };

  const handleSimulatedUpload = (e) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setUploadedPreview(url);
      // Auto-match for user convenience
      handleDiagnose();
    }
  };

  const handleReset = () => {
    setSelectedCrop('tomato');
    setSelectedPart('leaf');
    setSelectedSymptoms(['brown-spots']);
    setActiveDiagnosis(null);
    setUploadedPreview(null);
  };

  return (
    <section id="doctor" className="py-16 sm:py-20 bg-cream-50/70 border-t border-forest-100">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Section Header */}
        <div className="text-center max-w-3xl mx-auto mb-12">
