            <Stethoscope className="w-4 h-4 text-forest-700" />
            <span>Pathology Diagnostic AI</span>
          </div>
          <h2 className="text-3xl sm:text-4xl font-black text-forest-950 tracking-tight">
            {t('doctor.title')}
