              </button>
            ))}
          </div>
        </div>

        {/* Message Thread */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50/50">
          {messages.map((msg, index) => {
            const isAi = msg.sender === 'ai';
            const textContent = typeof msg.text === 'object'
              ? (msg.text[currentLang] || msg.text.en)
