                  <div className="w-8 h-8 rounded-xl bg-forest-800 text-amber-300 flex items-center justify-center shrink-0 mt-0.5 shadow-xs">
                    <Bot className="w-4 h-4" />
                  </div>
                )}

                <div
                  className={`max-w-[85%] rounded-2xl p-4 text-xs leading-relaxed shadow-xs ${
                    isAi
                      ? 'bg-white text-gray-800 border border-forest-100 whitespace-pre-line'
                      : 'bg-amber-600 text-white font-medium'
                  }`}
                >
                  <p>{textContent}</p>
                  <span className={`block text-[10px] mt-2 font-mono ${
                    isAi ? 'text-gray-400' : 'text-amber-200'
                  }`}>
                    {msg.time}
                  </span>
                </div>

                {!isAi && (
                  <div className="w-8 h-8 rounded-xl bg-amber-500 text-white flex items-center justify-center shrink-0 mt-0.5">
                    <User className="w-4 h-4" />
                  </div>
                )}
              </div>
            );
          })}

          {/* Listening indicator */}
          {isListening && (
            <div className="flex items-center gap-2 p-3 rounded-xl bg-amber-100 text-amber-900 text-xs font-bold animate-pulse">
              <Mic className="w-4 h-4 text-amber-700" />
