// AgriSense Express API Service
// Production-ready mock API layer designed for clean plug-ins to real external APIs (IMD, Agmarknet, OpenWeather)

import express from 'express';
import cors from 'cors';

const app = express();
const PORT = process.env.PORT || 3001;

app.use(cors());
app.use(express.json());

// Health Check
app.get('/api/health', (req, res) => {
  res.json({ status: 'ok', service: 'AgriSense API Service', timestamp: new Date().toISOString() });
});

// Recommend crops endpoint
app.post('/api/recommend-crops', (req, res) => {
  const { season, soilType, climateZone, nitrogen, phosphorus, potassium, ph } = req.body;
  res.json({
    success: true,
    message: 'Agronomic suitability calculated',
    query: { season, soilType, climateZone, nitrogen, phosphorus, potassium, ph }
  });
});

// Disease diagnostic endpoint
app.post('/api/diagnose', (req, res) => {
  const { cropId, plantPart, symptoms } = req.body;
  res.json({
    success: true,
    cropId,
    plantPart,
    symptoms
  });
});

// Weather endpoint
app.get('/api/weather/:district', (req, res) => {
  const { district } = req.params;
  res.json({
    district,
    source: 'AgroClimatic Micro-Station Simulator',
    status: 'Optimal'
  });
});

// Mandi rates endpoint
app.get('/api/mandi-prices', (req, res) => {
  res.json({
    status: 'active',
    lastUpdated: new Date().toISOString()
  });
});

if (process.env.NODE_ENV !== 'test') {
  app.listen(PORT, () => {
    console.log(`AgriSense API server listening on http://localhost:${PORT}`);
  });
}

export default app;

